<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import {request} from './api';
import {errorMessage} from './workbench';
const props=defineProps<{token:string;userId:string;tenantId:string}>();
const emit=defineEmits<{navigate:[page:string];busy:[value:boolean]}>();
type Row={number:number;source:string[];state:string;error:string;warnings:string[];product_id:string|null};
type Job={id:string;version:number;status:string;rows:Row[];new_categories:string[];counts:Record<string,number>};
type Prep={preview_products:{name:string;spec:string;unit:string;status:string;reference_price:string|null}[];store:Record<string,any>|null;steps:{id:string;label:string;complete:boolean}[];product_count:number;category_count:number;notice:string};
const prep=ref<Prep|null>(null),job=ref<Job|null>(null),jobs=ref<{id:string;status:string;created_at:string}[]>([]);
const busy=ref(false),error=ref(''),notice=ref(''),csv=ref(''),newCategories=ref(false),duplicates=ref(false),confirmed=ref(false),stop=ref(false),template=ref(''),maxBytes=ref(524288),previewVisible=ref(false),page=ref(1);
const root=`/api/v1/merchant/tenants/${props.tenantId}`;
let alive=true;let previewKey=crypto.randomUUID();let previewBody='';
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';emit('busy',true);try{await fn();}catch(e){if(alive)error.value=errorMessage(e);}finally{if(alive){busy.value=false;emit('busy',false);}}}
async function reload(){const [p,t,list]=await Promise.all([request<Prep>(root+'/preparation',props.token),request<{csv:string;max_bytes:number}>(root+'/catalog-imports/template',props.token),request<{items:typeof jobs.value}>(root+`/catalog-imports?page=${page.value}`,props.token)]);if(alive){prep.value=p;template.value=t.csv;maxBytes.value=t.max_bytes;jobs.value=list.items;}}
async function readJob(id:string){const data=await request<Job>(root+'/catalog-imports/'+id,props.token);if(alive){job.value=data;confirmed.value=false;newCategories.value=false;duplicates.value=false;}return data;}
function download(text:string,name:string){const url=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),0);}
async function file(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;await action(async()=>{if(!/\.csv$/i.test(f.name))throw Error('CSV_FILE_TYPE');if(f.size>maxBytes.value)throw Error('CSV_SIZE_LIMIT');let text:string;try{text=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());}catch{throw Error('CSV_UTF8_REQUIRED');}if(alive){csv.value=text;job.value=null;notice.value='文件已读取，请先预览；尚未创建商品。';}});}
async function preview(){await action(async()=>{if(new TextEncoder().encode(csv.value).length>maxBytes.value)throw Error('CSV_SIZE_LIMIT');if(previewBody!==csv.value){previewBody=csv.value;previewKey=crypto.randomUUID();}const data=await request<Job>(root+'/catalog-imports',props.token,'POST',{csv_text:previewBody},previewKey);if(alive){previewBody='';previewKey=crypto.randomUUID();job.value=data;confirmed.value=false;newCategories.value=false;duplicates.value=false;notice.value='预览只保存导入任务，没有创建商品。无效行不会执行。';}await reload();});}
async function accept(){if(!job.value||!confirmed.value)return;const id=job.value.id,version=job.value.version;await action(async()=>{const data=await request<Job>(root+`/catalog-imports/${id}/confirm`,props.token,'POST',{expected_version:version,confirmed:true,allow_new_categories:newCategories.value,allow_duplicates:duplicates.value},crypto.randomUUID());if(alive){job.value=data;notice.value='已确认。点击创建草稿开始执行，可随时停止后续行。';}});}
async function execute(){if(!job.value)return;const id=job.value.id;await action(async()=>{stop.value=false;let data=await readJob(id);if(data.status!=='CONFIRMED')throw Error('请先确认预览');for(const row of data.rows){if(!alive||stop.value)break;if(row.state==='SUCCESS'||row.state==='INVALID')continue;const change=await request<{version:number;row:Partial<Row>&{number:number}}>(root+`/catalog-imports/${id}/rows/${row.number}`,props.token,'POST',{expected_version:data.version},crypto.randomUUID());data={...data,version:change.version,rows:data.rows.map(r=>r.number===change.row.number?{...r,...change.row}:r)};data.counts=Object.fromEntries(['PENDING','INVALID','FAILED','SUCCESS'].map(state=>[state,data.rows.filter(r=>r.state===state).length]));if(alive)job.value=data;}if(alive)notice.value='本次执行已结束；成功行不会重建。结果不确定时先重新读取任务再继续。';await reload();});}
async function errors(){if(!job.value)return;const id=job.value.id;await action(async()=>{const data=await request<{csv:string;note:string}>(root+`/catalog-imports/${id}/errors`,props.token);if(alive){download(data.csv,'local-shop-import-errors.csv');notice.value=data.note;}});}
onMounted(()=>void action(reload));onUnmounted(()=>{alive=false;stop.value=true;csv.value='';job.value=null;prep.value=null;emit('busy',false);});
</script>
<template><section aria-label="开店准备与商品导入" :aria-busy="busy">
<h2>开店准备</h2><p>干货、茶叶、五金都使用同一套店铺；没有商品也能先记单，商品清单可稍后完善。</p>
<p v-if="error" role="alert" class="error">{{error}}；可重新读取服务端任务核对结果，勿盲目重复新建。</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="prep"><ol><li v-for="step in prep.steps" :key="step.id">{{step.complete?'已具备':'待完善/待接入'}} · {{step.label}}</li></ol><p>有效分类 {{prep.category_count}}，未归档商品 {{prep.product_count}}。{{prep.notice}}</p>
<div class="actions"><button :disabled="busy" @click="emit('navigate','workbench')">稍后完善，直接记单/店铺资料</button><button :disabled="busy" @click="emit('navigate','catalog')">维护分类与商品</button><button :disabled="busy" @click="previewVisible=!previewVisible">{{previewVisible?'关闭店内预览':'店内预览'}}</button><button :disabled="busy" @click="action(reload)">刷新准备进度</button></div>
<article v-if="previewVisible" aria-label="店内预览"><template v-if="prep.store"><h3>{{prep.store.name}}</h3><p class="raw">{{prep.store.description}}</p><p>{{prep.store.public_contact}} · {{prep.store.public_address}}</p><p>{{prep.store.business_hours}}</p><p>{{prep.store.delivery_note}}</p><p>自提：{{prep.store.allow_pickup?'提供':'未开放'}} / 配送：{{prep.store.allow_delivery?'提供':'未开放'}}；{{prep.store.published?'已发布配置':'尚未发布'}}</p></template><p v-else>请先在店铺资料中保存店名、经营联系信息与交付说明。</p><ul><li v-for="(product,index) in prep.preview_products" :key="index">{{product.name}} · {{product.spec}} · {{product.unit}} · {{product.status}} · 参考价 {{product.reference_price??'待确认'}}</li></ul><p>最多预览20件；完整清单在商品维护。</p><p>这是店内配置预览，不代表微信布局或真实分享已验证。真实微信分享/二维码待接入。</p></article></template>
<h3>CSV 商品清单导入</h3><p>最多200行、8列、{{maxBytes}}字节，UTF-8 CSV。只新增草稿，不自动发布、不覆盖、不下载远程图片。供货说明：常备 / 待确认 / 暂缺。</p>
<button :disabled="busy||!template" @click="download(template,'local-shop-products-template.csv')">下载CSV模板</button><label>选择CSV文件<input type="file" accept=".csv,text/csv" :disabled="busy" @change="file"/></label>
<label>CSV文本预览（可粘贴模板内容）<textarea v-model="csv" :disabled="busy" maxlength="524288"/></label><button :disabled="busy||!csv" @click="preview">解析并预览</button>
<article v-if="job" aria-label="导入任务"><h3>任务 {{job.id}} · {{job.status}}</h3><p>成功 {{job.counts.SUCCESS}} / 尚未执行 {{job.counts.PENDING}} / 无效 {{job.counts.INVALID}} / 失败 {{job.counts.FAILED}}</p><p>拟新增分类：{{job.new_categories.join('、')||'无'}}</p>
<template v-if="job.status==='PREVIEW'"><label class="check"><input type="checkbox" v-model="newCategories" :disabled="busy"/>允许创建上列新分类</label><label class="check"><input type="checkbox" v-model="duplicates" :disabled="busy"/>已核对疑似重复，仍明确允许新增（绝不覆盖）</label><label class="check"><input type="checkbox" v-model="confirmed" :disabled="busy"/>已核对有效行，仅创建商品草稿</label><button :disabled="busy||!confirmed||(job.new_categories.length>0&&!newCategories)||(job.rows.some(r=>r.warnings.length>0)&&!duplicates)" @click="accept">确认导入范围</button></template>
<div class="actions"><button v-if="job.status==='CONFIRMED'" :disabled="busy" @click="execute">创建草稿/继续未完成行</button><button v-if="busy" @click="stop=true">停止后续行</button><button :disabled="busy" @click="action(()=>readJob(job!.id).then(()=>{}))">重新读取此任务</button><button :disabled="busy" @click="errors">下载结果/错误清单</button></div>
<div class="import-scroll"><table><thead><tr><th>行</th><th>商品/规格/单位</th><th>状态</th><th>错误与提示</th></tr></thead><tbody><tr v-for="row in job.rows" :key="row.number"><td>{{row.number}}</td><td>{{row.source[0]}} / {{row.source[2]}} / {{row.source[3]}}</td><td>{{row.state}}</td><td>{{row.error}} {{row.warnings.join('；')}}</td></tr></tbody></table></div></article>
<h3>本店已有导入任务</h3><button :disabled="busy" @click="action(reload)">刷新任务</button><ul><li v-for="item in jobs" :key="item.id"><button :disabled="busy" @click="action(()=>readJob(item.id).then(()=>{}))">读取 {{item.created_at}} · {{item.status}} · {{item.id}}</button></li></ul><button :disabled="busy||page===1" @click="page--;action(reload)">上一页任务</button><button :disabled="busy||jobs.length<20" @click="page++;action(reload)">下一页任务</button>
</section></template>
<style scoped>.import-scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #dde4df;text-align:left;overflow-wrap:anywhere}button{max-width:100%;overflow-wrap:anywhere}</style>
